SELECT inventory.id, inventory.product_id, inventory.store_id, inventory.quantity, store_sales.store_id store_sale_store_id, store_sales.product_id store_sale_product_id, store_sales.units FROM inventory LEFT JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id WHERE inventory.product_id = 4 ORDER BY inventory.quantity DESC, inventory.product_id DESC
